// Exact necessary coverage check for r9/a7/III union size19. No SAT or new-edge completion search.
// Input: the existing complete brown57.edges. See BROWN_R9_SEVEN_III_OBSTRUCTION.md.
#include <bits/stdc++.h>
using namespace std;using U=uint64_t;int pc(U x){return __builtin_popcountll(x);}int lo(U x){return __builtin_ctzll(x);}const U ALL=(1ULL<<57)-1;
int main(int argc,char**argv){ifstream f(argv[1]);int n,m;f>>n>>m;U a[57]={},C=0,I=0,E;vector<pair<int,int>>ed;for(int u,v;f>>u>>v;){a[u]|=1ULL<<v;a[v]|=1ULL<<u;ed.push_back({u,v});}for(int v=0;v<57;v++)if(pc(a[v])==7)C|=1ULL<<v;for(int v=0;v<57;v++)if(!(C>>v&1)&&!(a[v]&C))I|=1ULL<<v;E=ALL^C^I;vector<U>T;for(auto[u,v]:ed)if((I>>u&1)&&(I>>v&1))for(int w=v+1;w<57;w++)if((I>>w&1)&&(a[u]>>w&1)&&(a[v]>>w&1))T.push_back((1ULL<<u)|(1ULL<<v)|(1ULL<<w));long long nodes=0,passes=0;int fam=0,cases=0;array<int,7>ix;
function<void(int,int)>outer=[&](int k,int st){if(k<7){for(int q=st;q<=14-(7-k);q++){ix[k]=q;outer(k+1,q+1);}return;}U unionT=0,R=0;for(int q:ix){R|=unionT&T[q];unionT|=T[q];}if(pc(unionT)!=19)return;fam++;assert(pc(R)==2);int central=-1;vector<U>base;for(int q:ix)if(pc(T[q]&R)==2)central=q;assert(central>=0);for(int q:ix)if(q!=central)base.push_back(T[q]);U missing=I&~unionT;vector<U>extra;for(U z=missing;z;z&=z-1){int v=lo(z);extra.push_back((1ULL<<v)|(a[v]&E));}assert(extra.size()==2&&!(extra[0]&extra[1]));vector<pair<int,int>>centraledges;for(auto[u,v]:ed)if((T[central]>>u&1)&&(T[central]>>v&1))centraledges.push_back({u,v});long long fn=nodes,fp=passes;
for(auto[cu,cv]:centraledges){U centralmask=(1ULL<<cu)|(1ULL<<cv);vector<U>affected,groups=extra;for(U t:base)if(t&centralmask)affected.push_back(t);else groups.push_back(t);vector<pair<int,int>>known{{cu,cv}};
function<void(int)>fixed=[&](int depth){if(depth<(int)affected.size()){U t=affected[depth];for(auto[u,v]:ed)if((t>>u&1)&&(t>>v&1)){known.push_back({u,v});fixed(depth+1);known.pop_back();}return;}cases++;U allowed=C,spare=0,cov[57];int d[57]={},gid[57];fill(gid,gid+57,-1);for(int v=0;v<57;v++)cov[v]=a[v]|(1ULL<<v);for(auto[u,v]:known){d[u]++;d[v]++;cov[u]&=~(1ULL<<v);cov[v]&=~(1ULL<<u);}for(int v=0;v<57;v++){if(d[v])allowed|=1ULL<<v;if(d[v]==2)spare|=1ULL<<v;}for(int g=0;g<(int)groups.size();g++){assert(!(allowed&groups[g]));allowed|=groups[g];for(U z=groups[g];z;z&=z-1)gid[lo(z)]=g;}int maxmiss=pc(spare);
function<void(U,U,U,U,int)>dfs=[&](U S,U avail,U covered,U ignored,int depth){nodes++;if(depth==8){if(pc(ALL&~covered)<=pc(S&spare)){passes++;if(passes<=4)cout<<"PASS family="<<fam<<" case="<<cases<<" S="<<S<<" uncovered="<<(ALL&~covered)<<" spare="<<(S&spare)<<"\n"<<flush;}return;}if(pc(avail)<8-depth)return;U unc=ALL&~covered&~ignored;int budget=maxmiss-pc(ignored);vector<int>gains;for(U z=avail;z;z&=z-1)gains.push_back(pc(cov[lo(z)]&unc));sort(gains.rbegin(),gains.rend());int upper=budget;for(int j=0;j<8-depth;j++)upper+=gains[j];if(upper<pc(unc))return;U choices=avail;int target=-1;if(unc){int best=58;for(U z=unc;z;z&=z-1){int u=lo(z);U poss=0;for(U q=avail;q;q&=q-1){int v=lo(q);if(cov[v]>>u&1)poss|=1ULL<<v;}if(pc(poss)<best){best=pc(poss);choices=poss;target=u;if(!best)break;}}if(budget>0)dfs(S,avail,covered,ignored|(1ULL<<target),depth);}
while(choices){int v=lo(choices);U bit=1ULL<<v;choices&=choices-1;avail&=~bit;U next=avail;int g=gid[v];if(g>=0){if(S&groups[g])next&=~groups[g];else next&=~(groups[g]&~a[v]);}dfs(S|bit,next,covered|cov[v],ignored,depth+1);}
};dfs(0,allowed,0,0,0);
};fixed(0);}cout<<"family="<<fam<<" cumulative_cases="<<cases<<" nodes="<<nodes-fn<<" passes="<<passes-fp<<"\n"<<flush;
};outer(0,0);cout<<"TOTAL families="<<fam<<" cases="<<cases<<" nodes="<<nodes<<" passes="<<passes<<"\n";}
